// CurbCutter service worker: keeps the whole app on the device so it opens instantly and works offline.
// The block between the stamp markers is generated by scripts/stamp-sw.mjs on every deploy.
// Never edit it by hand: a new VERSION is how phones learn that an update is ready.

// <stamp>
const VERSION = 'curbcut-58f0866bf596';
const FILES = [
  './',
  'assets/app.css',
  'assets/fonts/OFL-AtkinsonHyperlegibleNext.txt',
  'assets/fonts/OFL-Overpass.txt',
  'assets/fonts/atkinson-hyperlegible-next-latin-400-italic.woff2',
  'assets/fonts/atkinson-hyperlegible-next-latin-400-normal.woff2',
  'assets/fonts/atkinson-hyperlegible-next-latin-700-normal.woff2',
  'assets/fonts/atkinson-hyperlegible-next-latin-800-normal.woff2',
  'assets/fonts/overpass-latin-800-normal.woff2',
  'assets/icons/apple-touch-icon.png',
  'assets/icons/favicon-32.png',
  'assets/icons/favicon.svg',
  'assets/icons/icon-192.png',
  'assets/icons/icon-512.png',
  'assets/icons/icon-maskable-512.png',
  'index.html',
  'js/config.js',
  'js/data/barriers.js',
  'js/data/contacts.js',
  'js/data/rights.js',
  'js/data/sources.js',
  'js/lib/dates.js',
  'js/lib/events.js',
  'js/lib/geo.js',
  'js/lib/ics.js',
  'js/lib/ladder.js',
  'js/lib/letters.js',
  'js/lib/parking.js',
  'js/lib/photos.js',
  'js/lib/settings.js',
  'js/lib/share.js',
  'js/lib/speech.js',
  'js/lib/store.js',
  'js/main.js',
  'js/screens/about.js',
  'js/screens/case.js',
  'js/screens/cases.js',
  'js/screens/help.js',
  'js/screens/home.js',
  'js/screens/letter.js',
  'js/screens/rights.js',
  'js/screens/settings.js',
  'js/screens/show.js',
  'js/screens/wizard.js',
  'js/ui/components.js',
  'js/ui/dom.js',
  'js/ui/photos.js',
  'js/ui/recorder.js',
  'manifest.webmanifest',
  'privacy/index.html',
  'support/index.html'
];
// </stamp>

// Where the app lives ("/" on curbcutter.org). Only this address gets the app shell.
const APP_ROOT = new URL('./', self.location).pathname;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(VERSION).then((cache) => cache.addAll(FILES.map((f) => new Request(f, { cache: 'reload' })))),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('curbcut-') && k !== VERSION).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// The page asks the waiting worker to take over only after the person taps "Update now".
self.addEventListener('message', (event) => {
  if (event.data === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // links to other websites go straight to the network

  if (req.mode === 'navigate') {
    if (url.pathname === APP_ROOT || url.pathname === `${APP_ROOT}index.html`) {
      // App shell: always answer from the cache so the app opens with no signal.
      event.respondWith(
        caches.open(VERSION).then((cache) => cache.match('index.html').then((hit) => hit || fetch(req))),
      );
      return;
    }
    // Plain pages such as /privacy/ and /support/: the live page first, the saved copy with no signal.
    const saved = url.pathname.slice(APP_ROOT.length) + (url.pathname.endsWith('/') ? 'index.html' : '');
    event.respondWith(
      fetch(req).catch(() => caches.open(VERSION)
        .then((cache) => cache.match(saved))
        .then((hit) => hit || Response.error())),
    );
    return;
  }

  event.respondWith(
    caches.open(VERSION).then((cache) => cache.match(req, { ignoreSearch: true }).then((hit) => {
      if (hit) return hit;
      return fetch(req).then((res) => {
        if (res.ok && res.type === 'basic') cache.put(req, res.clone());
        return res;
      });
    })),
  );
});
